import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    host: '0.0.0.0',
    port: 5000,
    strictPort: true,
    allowedHosts: true
  }
})

/** @type {import('tailwindcss').Config} */
export default {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  theme: {
    extend: {
      colors: {
        or: '#C9A84C',
        'or-light': '#E8D5A0',
        'or-pale': '#F5EDD8',
        noir: '#0A0A0A',
        'noir-2': '#111111',
        'noir-3': '#1A1A1A',
        blanc: '#F5F0E8',
        texte: '#B8B0A0',
      },
      fontFamily: {
        cormorant: ['"Cormorant Garamond"', 'serif'],
        jost: ['Jost', 'sans-serif'],
      },
    },
  },
  plugins: [],
}

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

@tailwind base;
@tailwind components;
@tailwind utilities;

* { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { background: #0A0A0A; color: #F5F0E8; font-family: 'Jost', sans-serif; overflow-x: hidden; }
h1, h2, h3, h4 { font-family: 'Cormorant Garamond', serif; }

.section-label {
  font-size: 0.68rem;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: #C9A84C;
  margin-bottom: 0.75rem;
}

.divider {
  width: 60px;
  height: 1px;
  background: #C9A84C;
  margin: 1.5rem 0 2.5rem;
}

@keyframes scrollLine {
  0% { opacity: 0; transform: scaleY(0); transform-origin: top; }
  50% { opacity: 1; transform: scaleY(1); transform-origin: top; }
  100% { opacity: 0; transform: scaleY(1); transform-origin: bottom; }
}

.scroll-line { animation: scrollLine 2s ease-in-out infinite; }

import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import { Link } from 'react-scroll'

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50)
    window.addEventListener('scroll', handleScroll)
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  const navLinks = [
    { label: 'Services', to: 'services' },
    { label: 'Réalisations', to: 'realisations' },
    { label: 'À propos', to: 'about' },
  ]

  return (
    <motion.nav
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6, ease: 'easeOut' }}
      style={{
        background: scrolled ? 'rgba(10,10,10,0.98)' : 'rgba(10,10,10,0.92)',
        borderBottom: '1px solid rgba(201,168,76,0.12)',
        backdropFilter: 'blur(12px)',
        WebkitBackdropFilter: 'blur(12px)',
      }}
      className="fixed top-0 left-0 right-0 z-50 transition-all duration-300"
    >
      <div className="max-w-7xl mx-auto px-6 lg:px-12 h-16 flex items-center justify-between">
        {/* Logo */}
        <Link to="hero" smooth duration={600} className="cursor-pointer flex-shrink-0">
          <span
            style={{ fontFamily: '"Cormorant Garamond", serif', letterSpacing: '0.25em' }}
            className="text-xl font-light uppercase"
          >
            <span className="text-or">SENAN</span>
            <span className="text-blanc ml-2">CONCEPT</span>
          </span>
        </Link>

        {/* Desktop nav */}
        <div className="hidden md:flex items-center gap-10">
          {navLinks.map((link) => (
            <Link
              key={link.to}
              to={link.to}
              smooth
              duration={600}
              offset={-64}
              className="cursor-pointer text-texte hover:text-or transition-colors duration-300"
              style={{ fontFamily: 'Jost, sans-serif', fontWeight: 300, fontSize: '0.78rem', letterSpacing: '0.15em', textTransform: 'uppercase' }}
            >
              {link.label}
            </Link>
          ))}
        </div>

        {/* CTA */}
        <div className="hidden md:block">
          <Link
            to="contact"
            smooth
            duration={600}
            offset={-64}
            className="cursor-pointer px-5 py-2 transition-all duration-300"
            style={{
              border: '1px solid #C9A84C',
              color: '#C9A84C',
              fontFamily: 'Jost, sans-serif',
              fontWeight: 400,
              fontSize: '0.75rem',
              letterSpacing: '0.15em',
              textTransform: 'uppercase',
            }}
            onMouseEnter={e => { e.currentTarget.style.background = '#C9A84C'; e.currentTarget.style.color = '#0A0A0A' }}
            onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = '#C9A84C' }}
          >
            Contactez-nous
          </Link>
        </div>

        {/* Mobile burger */}
        <button
          className="md:hidden flex flex-col gap-1.5 p-2"
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label="Menu"
        >
          <span className={`block h-px w-6 bg-or transition-all duration-300 ${menuOpen ? 'rotate-45 translate-y-2' : ''}`} />
          <span className={`block h-px w-6 bg-or transition-all duration-300 ${menuOpen ? 'opacity-0' : ''}`} />
          <span className={`block h-px w-6 bg-or transition-all duration-300 ${menuOpen ? '-rotate-45 -translate-y-2' : ''}`} />
        </button>
      </div>

      {/* Mobile menu */}
      {menuOpen && (
        <div className="md:hidden px-6 pb-6 flex flex-col gap-6" style={{ background: 'rgba(10,10,10,0.98)' }}>
          {navLinks.map((link) => (
            <Link
              key={link.to}
              to={link.to}
              smooth
              duration={600}
              offset={-64}
              onClick={() => setMenuOpen(false)}
              className="cursor-pointer text-texte hover:text-or transition-colors duration-300"
              style={{ fontFamily: 'Jost, sans-serif', fontWeight: 300, fontSize: '0.78rem', letterSpacing: '0.15em', textTransform: 'uppercase' }}
            >
              {link.label}
            </Link>
          ))}
          <Link
            to="contact"
            smooth
            duration={600}
            offset={-64}
            onClick={() => setMenuOpen(false)}
            className="cursor-pointer text-center py-2 mt-2"
            style={{ border: '1px solid #C9A84C', color: '#C9A84C', fontFamily: 'Jost, sans-serif', fontSize: '0.75rem', letterSpacing: '0.15em', textTransform: 'uppercase' }}
          >
            Contactez-nous
          </Link>
        </div>
      )}
    </motion.nav>
  )
}

import { motion } from 'framer-motion'
import { Link } from 'react-scroll'

const fadeUp = (delay) => ({
  initial: { opacity: 0, y: 30 },
  animate: { opacity: 1, y: 0 },
  transition: { duration: 0.8, ease: 'easeOut', delay },
})

export default function Hero() {
  return (
    <section
      id="hero"
      className="min-h-screen flex flex-col items-center justify-center relative px-6"
      style={{
        background: 'radial-gradient(ellipse 60% 50% at 50% 60%, rgba(201,168,76,0.05) 0%, #0A0A0A 70%)',
      }}
    >
      <div className="text-center max-w-4xl mx-auto">
        {/* Eyebrow */}
        <motion.p {...fadeUp(0.2)} className="section-label mb-6">
          Art · Costume · Décoration
        </motion.p>

        {/* H1 */}
        <motion.h1
          {...fadeUp(0.4)}
          style={{
            fontFamily: '"Cormorant Garamond", serif',
            fontWeight: 300,
            fontSize: 'clamp(3rem, 8vw, 6.5rem)',
            lineHeight: 1.08,
            letterSpacing: '-0.01em',
          }}
          className="text-blanc mb-6"
        >
          L'art du costume
          <br />
          à l'âme{' '}
          <em style={{ color: '#C9A84C', fontStyle: 'italic' }}>africaine</em>
        </motion.h1>

        {/* Sous-titre */}
        <motion.p
          {...fadeUp(0.6)}
          className="text-texte max-w-xl mx-auto mb-10"
          style={{ fontFamily: 'Jost, sans-serif', fontWeight: 300, fontSize: '0.95rem', lineHeight: 1.85 }}
        >
          Tenues artistiques sur-mesure, décoration d'intérieure et création de poufs —
          au service des rois, des festivals et des mémoires culturelles.
        </motion.p>

        {/* Boutons */}
        <motion.div {...fadeUp(0.8)} className="flex flex-wrap items-center justify-center gap-4">
          <Link
            to="realisations"
            smooth
            duration={600}
            offset={-64}
            className="cursor-pointer px-8 py-3 transition-all duration-300"
            style={{
              background: '#C9A84C',
              color: '#0A0A0A',
              fontFamily: 'Jost, sans-serif',
              fontWeight: 500,
              fontSize: '0.8rem',
              letterSpacing: '0.15em',
              textTransform: 'uppercase',
            }}
            onMouseEnter={e => { e.currentTarget.style.background = '#E8D5A0' }}
            onMouseLeave={e => { e.currentTarget.style.background = '#C9A84C' }}
          >
            Nos réalisations
          </Link>
          <Link
            to="contact"
            smooth
            duration={600}
            offset={-64}
            className="cursor-pointer px-8 py-3 transition-all duration-300"
            style={{
              background: 'transparent',
              border: '1px solid rgba(245,240,232,0.3)',
              color: '#F5F0E8',
              fontFamily: 'Jost, sans-serif',
              fontWeight: 300,
              fontSize: '0.8rem',
              letterSpacing: '0.15em',
              textTransform: 'uppercase',
            }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = '#C9A84C'; e.currentTarget.style.color = '#C9A84C' }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(245,240,232,0.3)'; e.currentTarget.style.color = '#F5F0E8' }}
          >
            Prendre contact
          </Link>
        </motion.div>
      </div>

      {/* Scroll indicator */}
      <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-3">
        <div
          className="scroll-line"
          style={{ width: '1px', height: '48px', background: 'rgba(201,168,76,0.5)' }}
        />
        <span
          style={{ fontFamily: 'Jost, sans-serif', fontWeight: 300, fontSize: '0.6rem', letterSpacing: '0.3em', color: 'rgba(184,176,160,0.6)', textTransform: 'uppercase' }}
        >
          Défiler
        </span>
      </div>
    </section>
  )
}

import { motion } from 'framer-motion'

const stats = [
  { value: '3+', label: 'Festivals majeurs' },
  { value: '100%', label: 'Fait à la main' },
  { value: '15+', label: "Années d'expérience" },
  { value: 'BJ', label: 'Bénin, Afrique de l\'Ouest' },
]

export default function About() {
  return (
    <section id="about" className="py-24 lg:py-32 px-6 lg:px-12" style={{ background: '#111111' }}>
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-16 lg:gap-24 items-start">

        {/* Colonne texte */}
        <motion.div
          initial={{ opacity: 0, x: -40 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8, ease: 'easeOut' }}
        >
          <p className="section-label">Notre identité</p>
          <h2
            style={{ fontFamily: '"Cormorant Garamond", serif', fontWeight: 300, fontSize: 'clamp(2rem, 4vw, 3rem)', lineHeight: 1.15 }}
            className="text-blanc"
          >
            L'excellence au service<br />de la culture
          </h2>
          <div className="divider" />

          <div className="space-y-5 mb-12">
            <p style={{ fontFamily: 'Jost, sans-serif', fontWeight: 300, lineHeight: 1.9, fontSize: '0.9rem' }} className="text-texte">
              Fondée au cœur de Cotonou, Senan Concept est une maison artisanale dédiée à la valorisation du patrimoine culturel béninois à travers la création de tenues artistiques d'exception. Chaque pièce que nous concevons est une ode à l'histoire, au sacré et à la beauté.
            </p>
            <p style={{ fontFamily: 'Jost, sans-serif', fontWeight: 300, lineHeight: 1.9, fontSize: '0.9rem' }} className="text-texte">
              Nos créations ont habillé les plus grandes cérémonies du Bénin — des costumes de cour de la royauté Fon aux tenues rituelles des Vodouns Days, en passant par les parures du Festival des Masques. Chaque événement est une occasion de tisser l'art et la mémoire.
            </p>
            <p style={{ fontFamily: 'Jost, sans-serif', fontWeight: 300, lineHeight: 1.9, fontSize: '0.9rem' }} className="text-texte">
              Au-delà de la costumerie, Senan Concept investit également la décoration d'intérieure et la fabrication artisanale de poufs, apportant la chaleur et l'authenticité de l'artisanat africain dans vos espaces de vie.
            </p>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-2 gap-px" style={{ border: '1px solid rgba(201,168,76,0.15)' }}>
            {stats.map((stat, i) => (
              <div
                key={i}
                className="p-6"
                style={{ border: '1px solid rgba(201,168,76,0.15)' }}
              >
                <p
                  style={{ fontFamily: '"Cormorant Garamond", serif', fontWeight: 300, fontSize: '2.8rem', color: '#C9A84C', lineHeight: 1 }}
                >
                  {stat.value}
