  { label: 'Localisation', value: 'Cotonou, Bénin' },
  { label: 'Email', value: 'contact@senanconcept.com' },
  { label: 'Téléphone', value: '+229 XX XX XX XX' },
  { label: 'Disponibilité', value: 'Lun – Ven, 8h – 18h' },
]

