                  {t.nom}
                </p>
                <p style={{ fontFamily: 'Jost, sans-serif', fontWeight: 300, fontSize: '0.72rem', color: active === i ? '#C9A84C' : 'rgba(184,176,160,0.5)', marginTop: '0.15rem' }}>
                  {t.tag}
